/**
 * Check the given apis. To support circular references, the apis should appear
 * in the given environment.
 */
public static ApiResult checkApis(Map<APIName, ApiIndex> apis,
                                  GlobalEnvironment env) {
    HashSet<Api> checkedApis = new HashSet<Api>();
    List<APIName> failedApis = new ArrayList<APIName>();
    Iterable<? extends StaticError> errors = new HashSet<StaticError>();

    for (Map.Entry<APIName, ApiIndex> api : apis.entrySet()) {
        TypeCheckerResult checked = checkCompilationUnit(api.getValue(), env, true);
        checkedApis.add((Api)checked.ast());
        if (!checked.isSuccessful()) failedApis.add(api.getKey());
        errors = IterUtil.compose(checked.errors(), errors);
    }
    return new ApiResult
        (IndexBuilder.buildApis(checkedApis,
                                env,
                                System.currentTimeMillis()).apis(),
         failedApis,
        }
        // Pass 'false' argument to TypeNormalizer constructor to indicate that 
        // additional bounds should not be added to naked type parameters that also 
        // appear naked in the comprises clause. (That conversion is now done in
        // PreDisambiguationDesugarPhase, in order to correct a bug in checking
        // that static arguments satisfy the corresponding parameters' bounds.
        // EricAllen 4/27/2011
        result.setAst(result.ast().accept(new TypeNormalizer()));
        // There should be no Inference vars left at this point
        if( errors.isEmpty() && STypesUtil.assertAfterTypeChecking(result.ast()) )
            bug("Result of typechecking still contains intermediate nodes.\n" +
                result.ast());
        //System.out.println("WF");
        errors.addAll(new TypeWellFormedChecker(index, env, typeAnalyzer).check());
        if ( ! errors.isEmpty() ) {
            result = addErrors(errors, result);
            return result;
        }
        //System.out.println("Overloading\n");
        // Check overloadings in this compilation unit.
        errors.addAll(new OverloadingChecker(index, env).checkOverloading());
        if ( ! errors.isEmpty() ) {
            result = addErrors(errors, result);
            return result;
        }
        //System.out.println("Export\n");
        if (!isApi) {
            // Check the set of exported APIs in this component.
            errors.addAll(ExportChecker.checkExports((ComponentIndex)index, env));
            result = addErrors(errors, result);
        }

        //System.out.println("Variance\n");
        // Hack: don't run the variance checker if running the interpreter
        if (!isApi && Shell.getCompiledExprDesugaring()) { 
            errors.addAll(VarianceChecker.run((Component) result.ast()));

        for ( t <- toSet(typesInComp.keySet) ; if NU.isTraitOrObject(typesInComp.get(t)) ) {
            val traitOrObject = typesInComp.get(t).asInstanceOf[TraitIndex]
            val traitKindAndName = (compilation_unit match { case _:ObjectTraitIndex => "object "; case _ => "trait " }) + NU.getName(traitOrObject.ast)
            // Extend the type analyzer with the collected static parameters
            val oldTypeAnalyzer = typeAnalyzer
            // Add static parameters of the enclosing trait or object
            typeAnalyzer = typeAnalyzer.extend(toListFromImmutable(traitOrObject.staticParameters),
                                               None)
            val oracle = new OverloadingOracle()(typeAnalyzer)
            /* The parameter type of a setter must be the same as the return type
             * of a getter with the same name, if any.
             */
            for ( f <- toSet(traitOrObject.setters.keySet) ) {
                if ( traitOrObject.getters.keySet.contains(f) ) {
                    val getter = traitOrObject.getters.get(f)
                    // Setter declarations are guaranteed to have a single parameter.
                    val param = traitOrObject.setters.get(f).parameters.get(0)
                    val span = getter.getSpan
                    if ( param.getIdType.isSome ) {
                        if (! isTrue(typeAnalyzer.equivalent(NU.optTypeOrPatternToType(param.getIdType).unwrap,
                                                      getter.getReturnType.unwrap))(typeAnalyzer) )
                            error(span,
                                  "The parameter type of a setter must be " +
                                  "the same as\n    the return type of a getter " +
                                  "with the same name, if any.")
                    }
                }
            }

            val tt = STypesUtil.declToTraitType(traitOrObject.ast)
	        val methodsR = allMethods(tt, typeAnalyzer)

	        for (f <- toSet(methodsR.firstSet) ; if isDeclaredName(f) ) {
                  val mset = toSet(methodsR.matchFirst(f))
	              val dottedMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaMethod] &&
	      	      		  		     	     	      m.asInstanceOf[JavaMethod].selfType.isSome })  // unsure why this second condition
	              checkMethodOverloading(traitKindAndName, f, toMethodArrows(dottedMethods), oracle)
	              val functionalMethods = mset.filter(x => x match { case (m, str, tt) => m.isInstanceOf[JavaFunction]})
	              checkMethodOverloading(traitKindAndName, f, toFunctionalMethodArrows(functionalMethods), oracle)
	        }
            typeAnalyzer = oldTypeAnalyzer
        }
        toJavaList(errors)
    }

    private def checkFancyRule(name: IdOrOpOrAnonymousName,
    	    		       dFunctions: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       fMethods: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			       oracle: OverloadingOracle) = {
      // These variables are used to improve the error message
      var x: ArrowType = null 
      var y: ArrowType = null  
      if (!dFunctions.forall(f => fMethods.forall( m => if (!(oracle.lteq(f._1,m._1))) true else { x = f._1; y = m._1; false } )))
